 void Schedule(){debounce.Stop();debounce.Start();}
 void SetupSpans(){spans.AllowUserToAddRows=true;spans.AllowUserToDeleteRows=true;spans.RowHeadersVisible=true;spans.AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill;
  spans.Columns.Add("Line","LINE ID");spans.Columns.Add("Span","SPAN");spans.Columns["Span"].ReadOnly=true;var mark=new DataGridViewComboBoxColumn{Name="Mark",HeaderText="BEAM MARK",DisplayStyle=DataGridViewComboBoxDisplayStyle.DropDownButton,FlatStyle=FlatStyle.Flat};spans.Columns.Add(mark);
  foreach(var c in new[]{new[]{"Ln","CLEAR SPAN Ln (m)"},new[]{"Left","LEFT SUPPORT WIDTH (mm)"},new[]{"Right","RIGHT SUPPORT WIDTH (mm)"},new[]{"Slab","SLAB THICKNESS (mm)"},new[]{"Qty","IDENTICAL LINES (first span)"}})spans.Columns.Add(c[0],c[1]);
  spans.Columns.Add(new DataGridViewCheckBoxColumn{Name="Include",HeaderText="IN ESTIMATE"});foreach(DataGridViewColumn c in spans.Columns)if(!c.ReadOnly)c.DefaultCellStyle.BackColor=ModernUi.Input;spans.Columns["Span"].FillWeight=40;spans.Columns["Include"].FillWeight=50;
  spans.DefaultValuesNeeded+=(s,e)=>{var prev=spans.Rows.Cast<DataGridViewRow>().LastOrDefault(r=>!r.IsNewRow);e.Row.Cells["Line"].Value=prev==null?"B1":prev.Cells["Line"].Value;e.Row.Cells["Mark"].Value=prev==null?null:prev.Cells["Mark"].Value;e.Row.Cells["Left"].Value=prev==null?"400":prev.Cells["Right"].Value;e.Row.Cells["Right"].Value=prev==null?"400":prev.Cells["Right"].Value;e.Row.Cells["Slab"].Value=prev==null?"100":prev.Cells["Slab"].Value;e.Row.Cells["Qty"].Value="1";e.Row.Cells["Include"].Value=true;};
  spans.CellValueChanged+=(s,e)=>{if(e.RowIndex>=0&&e.ColumnIndex>=0&&spans.Columns[e.ColumnIndex].Name=="Ln")SpanInMetres(spans.Rows[e.RowIndex]);if(!filling)Schedule();};spans.RowsRemoved+=(s,e)=>{if(!filling)Schedule();};spans.CurrentCellDirtyStateChanged+=(s,e)=>{if(spans.IsCurrentCellDirty&&spans.CurrentCell is DataGridViewCheckBoxCell)spans.CommitEdit(DataGridViewDataErrorContexts.Commit);};spans.DataError+=(s,e)=>{e.ThrowException=false;};
  RowDeleteAffordance.Attach(spans);GridAppearance.Apply(spans);/* full column captions, wrapped (owner: no abbreviations) */spans.ColumnHeadersDefaultCellStyle.WrapMode=DataGridViewTriState.True;spans.ColumnHeadersHeightSizeMode=DataGridViewColumnHeadersHeightSizeMode.AutoSize;}
 void LoadSchedule(){using(var d=new OpenFileDialog{Filter="Beam schedule DXF (*.dxf)|*.dxf",Multiselect=true}){if(d.ShowDialog(this)!=DialogResult.OK)return;var files=d.FileNames.Select(path=>{var f=PowSourceFiles.ReadFile(path,"Beam DXF");return new[]{f.Text(),f.Name};}).ToList();AddSources(files,true);}}
 internal void AddSources(IEnumerable<string[]> files,bool replace){var parsed=new List<KeyValuePair<string[],Analysis>>();foreach(var f in files)parsed.Add(new KeyValuePair<string[],Analysis>(f,ManualBeamSchedule.Read(f[0],f[1])));
  var marks=new Dictionary<string,BeamRow>(StringComparer.OrdinalIgnoreCase);if(!replace)foreach(var kv in schedule)marks[kv.Key]=kv.Value;foreach(var kv in parsed)foreach(var row in kv.Value.Source){if(marks.ContainsKey(row.Mark))throw new Exception("Beam mark "+row.Mark+" appears in more than one schedule. Load each mark once.");marks[row.Mark]=row;}
  if(replace)sources.Clear();sources.AddRange(parsed.Select(p=>p.Key));schedule.Clear();foreach(var kv in marks)schedule[kv.Key]=kv.Value;
  var column=(DataGridViewComboBoxColumn)spans.Columns["Mark"];column.Items.Clear();foreach(var m in schedule.Keys.OrderBy(k=>k,StringComparer.OrdinalIgnoreCase))column.Items.Add(m);
  foreach(DataGridViewRow r in spans.Rows)if(!r.IsNewRow&&r.Cells["Mark"].Value!=null&&!schedule.ContainsKey(Convert.ToString(r.Cells["Mark"].Value)))r.Cells["Mark"].Value=null;
  source.Text="Schedule: "+string.Join(", ",sources.Select(s=>s[1]))+" - "+schedule.Count+" beam marks ("+string.Join(", ",schedule.Keys.Take(12))+(schedule.Count>12?", ...":"")+").";Schedule();}
 /* owner (20 November 2026, "clear span in m"): the clear span is entered and shown in metres; a value over 50 typed in
    millimetres (5000) is changed to metres (5) in the cell itself */
 static void SpanInMetres(DataGridViewRow r){double v;if(r.IsNewRow||!double.TryParse(Cell(r,"Ln"),NumberStyles.Float,Inv,out v)||v<=50||double.IsInfinity(v))return;r.Cells["Ln"].Value=(v/1000).ToString("0.###",Inv);}
 static string Cell(DataGridViewRow r,string name){return Convert.ToString(r.Cells[name].Value,Inv).Trim();}
 static double Read(string text,string what,int row){double v;if(!double.TryParse(text,NumberStyles.Float,Inv,out v)||double.IsNaN(v)||double.IsInfinity(v))throw new Exception("Row "+row+": enter "+what+" as a number.");return v;}
 List<CutSpan> SpanInputs(){var list=new List<CutSpan>();int index=0;string line=null;int number=0;foreach(DataGridViewRow r in spans.Rows){if(r.IsNewRow)continue;index++;string id=Cell(r,"Line");if(id==""&&Cell(r,"Mark")==""&&Cell(r,"Ln")=="")continue;if(id=="")throw new Exception("Row "+index+": enter the line ID.");
   number=string.Equals(id,line,StringComparison.OrdinalIgnoreCase)?number+1:1;line=id;filling=true;try{r.Cells["Span"].Value=number;}finally{filling=false;}
   int qty;if(!int.TryParse(Cell(r,"Qty")==""?"1":Cell(r,"Qty"),out qty))throw new Exception("Row "+index+": identical lines must be a whole number.");
   /* owner (20 November 2026): clear span in metres; a value over 50 left in millimetres is still read as mm */double ln=Read(Cell(r,"Ln"),"the clear span",index);if(ln>50)ln/=1000;
   list.Add(new CutSpan{Line=id,Mark=Cell(r,"Mark"),Ln=ln,LeftSupport=Read(Cell(r,"Left"),"the left support width",index)/1000,RightSupport=Read(Cell(r,"Right"),"the right support width",index)/1000,Slab=(Cell(r,"Slab")==""?0:Read(Cell(r,"Slab"),"the slab thickness",index))/1000,Quantity=qty,Include=!(r.Cells["Include"].Value is bool)||(bool)r.Cells["Include"].Value});}
  return list;}
 CutSettings Settings(){var name=Convert.ToString(config.SelectedItem);var cfg=CalculationStore.All().FirstOrDefault(c=>c.Name==name);if(cfg==null)throw new Exception("Choose a Splice, Development & Hooks configuration.");
  var lengths=stocks.Text.Split(new[]{',',' ',';'},StringSplitOptions.RemoveEmptyEntries).Select(t=>{double v;if(!double.TryParse(t,NumberStyles.Float,Inv,out v))throw new Exception("Commercial lengths: "+t+" is not a number.");return v;}).Distinct().OrderBy(v=>v).ToList();CommercialBars.Available(lengths);
  double roundStep=0;var rt=rounding.Text.Trim().ToLowerInvariant().Replace("mm","").Trim();if(rt!=""&&rt!="exact"&&rt!="0"&&(!double.TryParse(rt,NumberStyles.Float,Inv,out roundStep)||roundStep<0||roundStep>500))throw new Exception("Round cut lengths: choose Exact, 5 or 25, or type a step in mm (1 to 500).");
  return new CutSettings{CutRounding=roundStep,SpacerDia=(int)spacerDia.Value,SpacerSpacing=(double)spacerSpacing.Value/1000,Config=cfg,SpecialMomentFrame=frame.SelectedIndex==0,Cover=(double)cover.Value,MaxBar=double.Parse(Convert.ToString(longest.SelectedItem),Inv),Stocks=lengths,EndZone=(double)endZone.Value/100,TieOffset=(double)offset.Value/1000,TopExtension=topExtension.SelectedIndex==0?.25:1.0/3,Allowance=allowance.SelectedIndex,Overrides=new Dictionary<string,CutOverride>(overrides,StringComparer.OrdinalIgnoreCase),Added=added.ToList()};}
 internal void Calculate(){if(cutGrid.IsCurrentCellInEditMode||spans.IsCurrentCellInEditMode||columnList.IsCurrentCellInEditMode||footingList.IsCurrentCellInEditMode){Schedule();return;}try{if(schedule.Count==0&&memberPieces.Count==0&&!columnList.Rows.Cast<DataGridViewRow>().Any(r=>!r.IsNewRow)&&!footingList.Rows.Cast<DataGridViewRow>().Any(r=>!r.IsNewRow)){status.Text="Load a beam schedule, or the columns, slabs and footings of the Bill of Quantities.";return;}var input=schedule.Count==0?new List<CutSpan>():SpanInputs();if(input.Count==0&&memberPieces.Count==0&&!columnList.Rows.Cast<DataGridViewRow>().Any(r=>!r.IsNewRow)&&!footingList.Rows.Cast<DataGridViewRow>().Any(r=>!r.IsNewRow)){status.Text="Enter the spans of each beam line.";Clear();return;}var s=Settings();
   BeamRow found;var result=input.Count==0?new CutResult():BeamCutting.Build(input,m=>schedule.TryGetValue(m??"",out found)?found:null,s);{var scheduled=ScheduledMembers(s,result.Notes);var members=memberPieces.Concat(scheduled).ToList();if(members.Count>0)BeamCutting.AddMembers(result,members,s);}last=result;lastSettings=s;lastSpans=input;Show(result);
   int ng=result.Splices.Count(c=>!c.Ok);status.ForeColor=result.Errors.Count+ng>0?Color.Firebrick:PowTheme.Teal;status.Text=(result.Errors.Count+ng>0?(result.Errors.Count+ng)+" item(s) to review"+(result.Errors.Count>0?": "+result.Errors[0]+(result.Errors.Count>1?" (more in the Review tab)":""):" - see the Splice zone check tab")+". ":"")+result.Pieces.Count+" cut groups, "+result.Splices.Count+" splices; included spans: rebar "+result.IncludedKg.ToString("N2")+" kg, concrete "+result.IncludedConcrete.ToString("N3")+" m3, forms "+result.IncludedFormwork.ToString("N2")+" m2.";}
  catch(Exception ex){status.ForeColor=Color.Firebrick;status.Text=ex.Message;}}
 static string Dim(double v){return v>0?v.ToString("0",Inv):"";}
 /* the cutting list is editable (owner, 19 November 2026: "Gawin interactive yung sa cutting list dapat minomodify din"):
    cut length and pieces of any bar; location and diameter of an added bar; Delete removes a bar (Reset edits brings it back) */
 const int CMark=0,CLocation=2,CDia=3,CCut=5,CPerLine=6,CEdited=13;
 void SetupEditing(){cutGrid.ReadOnly=false;cutGrid.AllowUserToDeleteRows=true;cutGrid.EditMode=DataGridViewEditMode.EditOnKeystrokeOrF2;
  cutGrid.CellEndEdit+=(s,e)=>{if(filling||e.RowIndex<0)return;var row=cutGrid.Rows[e.RowIndex];var piece=row.Tag as CutPiece;if(piece==null)return;string text=Convert.ToString(row.Cells[e.ColumnIndex].Value,Inv).Trim();try{ApplyEdit(piece,e.ColumnIndex,text);}catch(Exception ex){MessageBox.Show(this,ex.Message,"Cutting list",MessageBoxButtons.OK,MessageBoxIcon.Information);}Schedule();};
  cutGrid.UserDeletingRow+=(s,e)=>{e.Cancel=true;var piece=e.Row.Tag as CutPiece;if(piece==null)return;if(MessageBox.Show(this,"Remove "+piece.BarMark+" ("+piece.Location+") from the cutting list?"+(piece.Manual?"":" Reset edits brings it back."),"Cutting list",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;if(piece.Manual)added.RemoveAll(a=>a.BarMark==piece.BarMark);else Override(piece.Id).Deleted=true;Schedule();};
  cutGrid.DataError+=(s,e)=>{e.ThrowException=false;};}
 CutOverride Override(string mark){CutOverride o;if(!overrides.TryGetValue(mark,out o)){o=new CutOverride();overrides[mark]=o;}return o;}
 internal void ApplyEdit(CutPiece piece,int column,string text){var manual=piece.Manual?added.FirstOrDefault(a=>a.BarMark==piece.BarMark):null;
  if(column==CCut){double v;if(!double.TryParse(text,NumberStyles.Float,Inv,out v)||v<=0||v>50)throw new Exception("Enter the cut length in metres (more than 0, up to 50).");if(manual!=null)manual.Length=v;else{double calc=piece.CalculatedLength??piece.Length;Override(piece.Id).Length=Math.Abs(v-calc)<1e-9?(double?)null:v;}}
  else if(column==CPerLine){int n;if(!int.TryParse(text,out n)||n<0||n>100000)throw new Exception("Enter the number of pieces per line (0 or more).");if(manual!=null)manual.PerLine=n;else{int calc=piece.CalculatedPerLine??piece.PerLine;Override(piece.Id).PerLine=n==calc?(int?)null:n;}}
  else if(column==CLocation&&manual!=null)manual.Location=text==""?"Added bar":text;
  else if(column==CDia&&manual!=null){int d;if(!int.TryParse(text,out d)||EstimatorEngine.UnitMass(d)<=0)throw new Exception("Enter a bar diameter in mm.");manual.Diameter=d;}
  foreach(var key in overrides.Where(k=>!k.Value.Deleted&&!k.Value.Length.HasValue&&!k.Value.PerLine.HasValue).Select(k=>k.Key).ToList())overrides.Remove(key);}
 void ConfigureEditing(CutResult r){filling=true;try{cutGrid.ReadOnly=false;foreach(DataGridViewColumn c in cutGrid.Columns)c.ReadOnly=c.Index!=CCut&&c.Index!=CPerLine;cutGrid.Columns[CCut].DefaultCellStyle.BackColor=cutGrid.Columns[CPerLine].DefaultCellStyle.BackColor=ModernUi.Input;
   for(int i=0;i<r.Pieces.Count&&i<cutGrid.Rows.Count;i++){var row=cutGrid.Rows[i];var p=r.Pieces[i];row.Tag=p;if(p.Manual){row.Cells[CLocation].ReadOnly=row.Cells[CDia].ReadOnly=false;row.Cells[CLocation].Style.BackColor=row.Cells[CDia].Style.BackColor=ModernUi.Input;}
    if(p.Manual||p.Edited){row.Cells[CEdited].Style.ForeColor=Color.DarkOrange;foreach(int c in new[]{CCut,CPerLine})row.Cells[c].Style.BackColor=Color.FromArgb(255,244,214);row.Cells[CCut].ToolTipText=p.CalculatedLength.HasValue?"Calculated: "+p.CalculatedLength.Value.ToString("0.000",Inv)+" m":"";row.Cells[CPerLine].ToolTipText=p.CalculatedPerLine.HasValue?"Calculated: "+p.CalculatedPerLine.Value+" pcs":"";}}}finally{filling=false;}}
 void AddBar(){if(last==null||lastSpans==null||lastSpans.Count==0)throw new Exception("Enter the beam lines first.");var current=cutGrid.CurrentRow==null?null:cutGrid.CurrentRow.Tag as CutPiece;string line=current!=null?current.Line:lastSpans[0].Line;int span=current!=null&&current.Span>0?current.Span:1;int n=1;while(added.Any(a=>a.BarMark==line+"-A"+n)||last.Pieces.Any(p=>p.BarMark==line+"-A"+n))n++;
  added.Add(new CutPiece{BarMark=line+"-A"+n,Line=line,Span=span,Diameter=12,Length=1,PerLine=1,Location="Added bar",Shape="Straight",Manual=true});Calculate();var row=cutGrid.Rows.Cast<DataGridViewRow>().FirstOrDefault(r=>Convert.ToString(r.Cells[CMark].Value)==line+"-A"+n);if(row!=null){cutGrid.CurrentCell=row.Cells[CLocation];}}
 void ResetEdits(){if(overrides.Count==0&&added.Count==0)return;if(MessageBox.Show(this,"Remove every edit and added bar and go back to the calculated cutting list?","Cutting list",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;overrides.Clear();added.Clear();Calculate();}
 Control BbsPanel(){var host=new Panel{Dock=DockStyle.Fill};var head=new FlowLayoutPanel{Dock=DockStyle.Top,AutoSize=true,Padding=new Padding(6,4,6,4),WrapContents=true};Field(head,"BBS no.",bbsNo);Field(head,"Revision",bbsRev);Field(head,"Status",bbsStatus);Field(head,"Prepared by",preparedBy);Field(head,"Checked by",checkedBy);Field(head,"Approved by",approvedBy);host.Controls.Add(bbsGrid);host.Controls.Add(shapeView);host.Controls.Add(head);
  bbsGrid.SelectionChanged+=(s,e)=>{var r=bbsGrid.CurrentRow;shapeView.Show(r==null?null:r.Tag as CutPiece);};
  bbsGrid.CellPainting+=(s,e)=>{if(e.RowIndex<0||e.ColumnIndex<0||bbsGrid.Columns[e.ColumnIndex].HeaderText!="SKETCH")return;var piece=bbsGrid.Rows[e.RowIndex].Tag as CutPiece;if(piece==null)return;e.PaintBackground(e.ClipBounds,false);var box=new RectangleF(e.CellBounds.X+4,e.CellBounds.Y+4,e.CellBounds.Width-8,e.CellBounds.Height-8);var state=e.Graphics.Save();e.Graphics.SetClip(e.CellBounds);BarShapes.Draw(e.Graphics,box,BarShapes.Sketch(piece),false,Color.FromArgb(25,90,160),Font);e.Graphics.Restore(state);e.Handled=true;};
  return host;}
 /* bar bending schedule for issue (owner: "Pati yung bar bending schedule. Yung pwedeng iissue for construction"); the names are typed by
    the user and the signature lines stay blank - the app never marks a schedule as approved */
 /* one report per kind of member: the kinds on the list are offered when there is more than one */
 void PrintMenu(Control anchor){if(last==null)throw new Exception("Nothing to schedule yet: load a schedule and enter the beam lines.");var kinds=BbsReport.Kinds.Where(k=>last.Pieces.Any(p=>p.Group==k)).ToList();if(kinds.Count==0)throw new Exception("Nothing to schedule yet: load a schedule and enter the beam lines.");
  if(kinds.Count==1){using(var doc=BbsReport.Build(last,lastSettings,Info(),kinds[0]))CalculationReportView.ShowReport(this,doc);return;}
  var menu=new ContextMenuStrip();foreach(var k in kinds){var kind=k;menu.Items.Add((kind=="Wall footing"?"Wall footings":kind+"s")+" report",null,(s,e)=>{try{using(var doc=BbsReport.Build(last,lastSettings,Info(),kind))CalculationReportView.ShowReport(this,doc);}catch(Exception ex){MessageBox.Show(this,ex.Message,"Cutting list",MessageBoxButtons.OK,MessageBoxIcon.Warning);}});}
  menu.Show(anchor??this,anchor==null?new Point(20,20):new Point(0,anchor.Height));}
 internal CalculationDocument BbsDocument(){if(last==null)throw new Exception("Nothing to schedule yet: load a schedule and enter the beam lines.");return BbsReport.Build(last,lastSettings,Info());}
 BbsInfo Info(){return new BbsInfo{Number=bbsNo.Text.Trim(),Revision=bbsRev.Text.Trim(),Status=Convert.ToString(bbsStatus.SelectedItem),Source=string.Join(", ",sources.Select(x=>x[1])),Curtailment=Convert.ToString(topExtension.SelectedItem)+" for extra top bars; extra bottom bars from L/6 off each face; main piece allowance: "+BeamCutting.AllowanceNames[lastSettings.Allowance],Prepared=preparedBy.Text,Checked=checkedBy.Text,Approved=approvedBy.Text};}
 internal string BbsText(){if(last==null)throw new Exception("Nothing to schedule yet: load a schedule and enter the beam lines.");var b=new StringBuilder();b.AppendLine("BAR BENDING SCHEDULE - BEAMS");b.AppendLine();b.Append(ProjectReportHeader());
  b.AppendLine("BBS no.: "+bbsNo.Text.Trim()+"   Revision: "+bbsRev.Text.Trim()+"   Date: "+DateTime.Now.ToString("yyyy-MM-dd",Inv)+"   Status: "+Convert.ToString(bbsStatus.SelectedItem));b.AppendLine("Schedule source: "+string.Join(", ",sources.Select(x=>x[1])));b.AppendLine();
  b.AppendLine("## 01  SCHEDULE");b.AppendLine("Member         Bar mark      Type/size     Mbrs  Each   Total  Length(mm)  Shape                          A      B      C      kg");
  foreach(var p in last.Pieces.Where(x=>x.PerLine>0))b.AppendLine(p.Member.PadRight(15)+p.BarMark.PadRight(14)+("G"+p.Grade+" "+p.Diameter+"mm").PadRight(14)+p.Lines.ToString(Inv).PadRight(6)+p.PerLine.ToString(Inv).PadRight(7)+p.Pieces.ToString(Inv).PadRight(7)+(p.Length*1000).ToString("0",Inv).PadRight(12)+BeamCutting.ShapeName(p.ShapeCode).PadRight(31)+Dim(p.DimA).PadRight(7)+Dim(p.DimB).PadRight(7)+Dim(p.DimC).PadRight(7)+p.Kg.ToString("0.00",Inv)+(p.Manual?"  (added)":p.Edited?"  (edited)":""));
  b.AppendLine();b.AppendLine("## 02  TOTALS");foreach(var g in last.Pieces.GroupBy(x=>new{x.Grade,x.Diameter}).OrderBy(x=>x.Key.Grade).ThenBy(x=>x.Key.Diameter))b.AppendLine("Grade "+g.Key.Grade+" "+g.Key.Diameter+" mm: "+g.Sum(x=>x.Pieces*x.Length).ToString("0.00",Inv)+" m, "+g.Sum(x=>x.Kg).ToString("0.00",Inv)+" kg");b.AppendLine("Total: "+last.Pieces.Sum(x=>x.Kg).ToString("0.00",Inv)+" kg");
  b.AppendLine();b.AppendLine("## 03  NOTES");b.AppendLine("Lengths and dimensions in millimetres. A, B, C are outside dimensions: L-bar A = straight, B = hook leg; U-bar A and C = hook legs, B = straight; hoop A x B = outside width x height, C = 135° hook tail; crosstie A = height, B = 135° tail, C = 90° tail.");b.AppendLine("Cut lengths include the bend allowances of the Splice, Development & Hooks configuration ("+lastSettings.Config.Name+") and are the values to cut; check the bent shape on site.");b.AppendLine("Curtailment: "+Convert.ToString(topExtension.SelectedItem)+" top extra bars, bottom extra bars from L/6 off each face; main piece allowance: "+BeamCutting.AllowanceNames[lastSettings.Allowance]+". Splices per the splice zone check.");
  if(last.Pieces.Any(x=>x.Manual||x.Edited)||last.Deleted.Count>0)b.AppendLine("Edited on the cutting list: "+last.Pieces.Count(x=>x.Edited&&!x.Manual)+" bar(s) changed, "+last.Pieces.Count(x=>x.Manual)+" added, "+last.Deleted.Count+" removed ("+string.Join(", ",last.Deleted.Select(x=>x.BarMark))+").");
  if(last.Errors.Count>0||last.Splices.Any(c=>!c.Ok))b.AppendLine("OPEN REVIEW ITEMS: "+(last.Errors.Count+last.Splices.Count(c=>!c.Ok))+" - resolve before issue (see the cutting list report).");
  b.AppendLine();b.AppendLine("## 04  ISSUE");b.AppendLine("Prepared by: "+Signatory(preparedBy)+"   Signature: ____________________   Date: ____________");b.AppendLine("Checked by:  "+Signatory(checkedBy)+"   Signature: ____________________   Date: ____________");b.AppendLine("Approved by: "+Signatory(approvedBy)+"   Signature: ____________________   Date: ____________");
  b.AppendLine("This schedule is valid for construction only when signed by the responsible engineer. Generated by DTCE Tool Kit v"+Engine.Version+"; the program does not approve it.");return b.ToString();}
 static string Signatory(TextBox t){string v=t.Text.Trim();return (v==""?"____________________":v).PadRight(28);}
 void Clear(){foreach(var g in new[]{cutGrid,spliceGrid,estimateGrid,buyGrid,bbsGrid,patternGrid,smfGrid}){g.Rows.Clear();g.Columns.Clear();}review.Text="";}
 static void Fill(DataGridView g,string[] headers,IEnumerable<object[]> rows){g.SuspendLayout();try{g.Rows.Clear();g.Columns.Clear();foreach(var h in headers)g.Columns.Add("c"+g.Columns.Count,h);foreach(var r in rows)g.Rows.Add(r);}finally{g.ResumeLayout();}}
 Control ModelPanel(){var host=new Panel{Dock=DockStyle.Fill};var bar=new FlowLayoutPanel{Dock=DockStyle.Top,AutoSize=true,Padding=new Padding(6,4,6,4)};bar.Controls.Add(new Label{Text="Beam line",AutoSize=true,Padding=new Padding(0,6,0,0)});bar.Controls.Add(modelLine);var fit=new Button{Text="Fit view",AutoSize=true};fit.Click+=(s,e)=>model.Fit();bar.Controls.Add(fit);/* always to true scale (owner, 20 November 2026: "laging naka true to scale") */model.TrueScale=true;
  modelLine.SelectedIndexChanged+=(s,e)=>{if(!filling&&last!=null)model.SetResult(last,Convert.ToString(modelLine.SelectedItem));};
  model.BarSelected+=mark=>{foreach(var grid in new[]{cutGrid,bbsGrid}){int col=grid==cutGrid?CMark:1;var row=grid.Rows.Cast<DataGridViewRow>().FirstOrDefault(r=>Convert.ToString(r.Cells[col].Value)==mark);if(row!=null){filling=true;try{grid.ClearSelection();row.Selected=true;grid.FirstDisplayedScrollingRowIndex=row.Index;}catch(Exception){}finally{filling=false;}}}status.ForeColor=PowTheme.Teal;status.Text="Selected "+mark+" - its row is selected in the bar bending schedule and the cutting list.";};
  foreach(var grid in new[]{cutGrid,bbsGrid}){var g=grid;g.SelectionChanged+=(s,e)=>{if(filling||g.CurrentRow==null)return;int col=g==cutGrid?CMark:1;if(g.Columns.Count>col)model.Selected=Convert.ToString(g.CurrentRow.Cells[col].Value);};}
  host.Controls.Add(model);host.Controls.Add(bar);return host;}
 void Show(CutResult r){ShowMembers(r);filling=true;try{string keep=Convert.ToString(modelLine.SelectedItem);modelLine.Items.Clear();foreach(var g in r.Geometry)modelLine.Items.Add(g.Line);if(modelLine.Items.Count>0)modelLine.SelectedItem=modelLine.Items.Contains(keep)?keep:modelLine.Items[0];}finally{filling=false;}model.SetResult(r,Convert.ToString(modelLine.SelectedItem));
  Fill(cutGrid,new[]{"BAR MARK","MEMBER","LOCATION","DIA (mm)","GRADE","CUT LENGTH (m)","PCS / LINE","LINES","TOTAL PCS","SHAPE","FROM (m)","TO (m)","WEIGHT (kg)","EDITED"},r.Pieces.Select(p=>new object[]{p.BarMark,p.Member,p.Location,p.Diameter,p.Grade,p.Length.ToString("0.000",Inv),p.PerLine,p.Lines,p.Pieces,p.Shape,p.Start.ToString("0.000",Inv),p.End.ToString("0.000",Inv),p.Kg.ToString("N2"),p.Manual?"added":p.Edited?"edited":""}));
  ConfigureEditing(r);
  Fill(bbsGrid,new[]{"MEMBER","BAR MARK","TYPE AND SIZE","NO. OF MEMBERS","NO. IN EACH","TOTAL NO.","LENGTH OF EACH BAR (mm)","SHAPE","SKETCH","A (mm)","B (mm)","C (mm)","D (mm)","E (mm)","WEIGHT (kg)"},r.Pieces.Where(p=>p.PerLine>0).Select(p=>new object[]{p.Member,p.BarMark,"G"+p.Grade+" "+p.Diameter+" mm",p.Lines,p.PerLine,p.Pieces,(p.Length*1000).ToString("0",Inv),BbsReport.Code(p.ShapeCode),"",Dim(p.DimA),Dim(p.DimB),Dim(p.DimC),Dim(p.DimD),Dim(p.DimE),p.Kg.ToString("N2")}));
  {var shown=r.Pieces.Where(p=>p.PerLine>0).ToList();for(int k=0;k<shown.Count&&k<bbsGrid.Rows.Count;k++){bbsGrid.Rows[k].Tag=shown[k];bbsGrid.Rows[k].Height=46;}if(bbsGrid.Columns.Count>8){var sk=bbsGrid.Columns[8];sk.MinimumWidth=130;sk.AutoSizeMode=DataGridViewAutoSizeColumnMode.None;sk.Width=140;}shapeView.Show(bbsGrid.CurrentRow==null?null:bbsGrid.CurrentRow.Tag as CutPiece);}
  Fill(spliceGrid,new[]{"LINE","BAR","DIA (mm)","SPAN","LAP FROM (m)","LAP TO (m)","LAP (m)","ALLOWED ZONE (m)","RESULT","NOTE"},r.Splices.Select(c=>new object[]{c.Line,c.Shown,c.Diameter,c.Span,c.From.ToString("0.000",Inv),c.To.ToString("0.000",Inv),c.Lap.ToString("0.000",Inv),c.ZoneFrom.ToString("0.000",Inv)+" - "+c.ZoneTo.ToString("0.000",Inv),c.Status,c.Note}));
  foreach(DataGridViewRow row in spliceGrid.Rows)if(Convert.ToString(row.Cells[8].Value)=="NG")row.DefaultCellStyle.ForeColor=Color.Firebrick;
  var dias=r.Spans.SelectMany(e=>e.KgByDiameter.Keys).Distinct().OrderBy(d=>d).ToList();
  Fill(estimateGrid,new[]{"LINE","SPAN","MARK","IN ESTIMATE","Ln (m)","IDENTICAL LINES"}.Concat(dias.Select(d=>d+" mm (kg)")).Concat(new[]{"REBAR (kg)","STIRRUP SETS","CONCRETE (m3)","FORMS (m2)"}).ToArray(),r.Spans.Select(e=>new object[]{e.Line,e.Span,e.Mark,e.Include?"Yes":"No",e.Ln.ToString("0.000",Inv),e.Quantity}.Concat(dias.Select(d=>{double v;return (object)(e.KgByDiameter.TryGetValue(d,out v)?v:0).ToString("N2");})).Concat(new object[]{e.Kg.ToString("N2"),e.Ties,e.Concrete.ToString("N3"),e.Formwork.ToString("N2")}).ToArray()).Concat(new[]{new object[]{"INCLUDED SPANS","","","","",""}.Concat(dias.Select(d=>(object)r.Spans.Where(e=>e.Include).Sum(e=>{double v;return e.KgByDiameter.TryGetValue(d,out v)?v:0;}).ToString("N2"))).Concat(new object[]{r.IncludedKg.ToString("N2"),r.Spans.Where(e=>e.Include).Sum(e=>e.Ties),r.IncludedConcrete.ToString("N3"),r.IncludedFormwork.ToString("N2")}).ToArray()}));
  foreach(DataGridViewRow row in estimateGrid.Rows)if(Convert.ToString(row.Cells[3].Value)=="No")row.DefaultCellStyle.ForeColor=Color.FromArgb(150,150,150);if(estimateGrid.Rows.Count>0)estimateGrid.Rows[estimateGrid.Rows.Count-1].DefaultCellStyle.Font=new Font(Font,FontStyle.Bold);
  Fill(buyGrid,new[]{"GRADE","DIA (mm)","CUT (m)","PIECES","STOCK LENGTH (m)","PCS / STOCK","BARS TO BUY","OFFCUT (m)"},r.Purchases.Select(p=>new object[]{p.Grade,p.Diameter,p.Cut.ToString("0.000",Inv),p.Pieces,p.Choice==null?"-":p.Choice.Length.ToString("0.##",Inv),p.Choice==null?"-":p.Choice.PiecesPerStock.ToString(Inv),p.Choice==null?"-":p.Choice.Bars.ToString(Inv),p.Choice==null?"-":p.Choice.Waste.ToString("0.00",Inv)}));
  Fill(patternGrid,new[]{"PATTERN","GRADE","DIA (mm)","STOCK (m)","NO. OF BARS","CUTS FROM EACH BAR","FOR BAR MARKS (total pieces)","OFFCUT (m)"},r.Patterns.Select(p=>new object[]{p.Id,p.Grade,p.Diameter,p.Stock.ToString("0.0#",Inv),p.Bars,CuttingPatterns.Describe(p),CuttingPatterns.MarksOf(p),p.Offcut.ToString("0.000",Inv)+(p.Offcut>=CuttingPatterns.ReusableOffcut?" (keep)":"")}).Concat(CuttingPatterns.Summary(r.Patterns).Select(o=>new object[]{"ORDER",o.Grade,o.Diameter,"",o.BarsByStock.Values.Sum(),string.Join(", ",o.BarsByStock.OrderByDescending(k=>k.Key).Select(k=>k.Value+" x "+k.Key.ToString("0.0#",Inv)+" m"))+"  -  "+o.Kg.ToString("N2")+" kg bought","cut "+o.Used.ToString("0.00",Inv)+" m",(o.Bought-o.Used).ToString("0.00",Inv)+" ("+o.WastePercent.ToString("0.0",Inv)+"%)"})));
  foreach(DataGridViewRow row in patternGrid.Rows)if(Convert.ToString(row.Cells[0].Value)=="ORDER")row.DefaultCellStyle.Font=new Font(Font,FontStyle.Bold);
  Fill(smfGrid,new[]{"LINE","SPAN","CHECK","CLAUSE","REQUIRED","PROVIDED","RESULT","NOTE"},r.Smf.Select(c=>new object[]{c.Line,c.Span>0?c.Span.ToString(Inv):"-",c.Item,c.Clause,c.Required,c.Provided,c.Ok?"OK":"NOT OK",c.Note}));
  foreach(DataGridViewRow row in smfGrid.Rows)if(Convert.ToString(row.Cells[6].Value)!="OK")row.DefaultCellStyle.ForeColor=Color.Firebrick;
  review.Text=(r.Deleted.Count>0?"Removed from the cutting list (Reset edits brings them back): "+string.Join(", ",r.Deleted.Select(d=>d.BarMark+" "+d.Location))+"\r\n\r\n":"")+(r.Errors.Count==0&&r.Splices.All(c=>c.Ok)&&r.Smf.All(c=>c.Ok)?"No items to review.\r\n\r\n"+string.Join("\r\n",r.Notes):"REVIEW\r\n"+string.Join("\r\n",r.Errors.Select(e=>"- "+e).Concat(r.Splices.Where(c=>!c.Ok).Select(c=>"- "+c.Line+" "+c.Bar+" span "+c.Span+": "+c.Note)).Concat(r.Smf.Where(c=>!c.Ok).Select(c=>"- "+c.Line+(c.Span>0?" span "+c.Span:"")+": "+c.Item+" ("+c.Clause+") - required "+c.Required+", provided "+c.Provided)))+"\r\n\r\n"+string.Join("\r\n",r.Notes));}
 internal string ReportText(){if(last==null)throw new Exception("Nothing to report yet: load a schedule and enter the beam lines.");var info=ProjectReportHeader();return info+BeamCutting.Report(last,lastSettings,lastSpans);}
 static string ProjectReportHeader(){try{var p=ProjectInfoStore.Read();if(p==null||string.IsNullOrWhiteSpace(p.Name))return "";return p.NameLine+"\r\n"+p.LocationLine+"\r\n\r\n";}catch(Exception){return "";}}
 static string Tsv(DataGridView g){var b=new StringBuilder();b.AppendLine(string.Join("\t",g.Columns.Cast<DataGridViewColumn>().Select(c=>c.HeaderText)));foreach(DataGridViewRow r in g.Rows)b.AppendLine(string.Join("\t",r.Cells.Cast<DataGridViewCell>().Select(c=>Convert.ToString(c.Value,Inv))));return b.ToString();}
 /* project file */
 internal string ProjectXml(){var doc=new XmlDocument();var root=doc.CreateElement("BeamCuttingList");root.SetAttribute("version","1");root.SetAttribute("appVersion",Engine.Version);doc.AppendChild(root);
  root.SetAttribute("config",Convert.ToString(config.SelectedItem));root.SetAttribute("frame",frame.SelectedIndex.ToString(Inv));root.SetAttribute("cover",cover.Value.ToString(Inv));root.SetAttribute("rounding",rounding.Text);root.SetAttribute("spacerDia",spacerDia.Value.ToString(Inv));root.SetAttribute("spacerSpacing",spacerSpacing.Value.ToString(Inv));root.SetAttribute("longest",Convert.ToString(longest.SelectedItem));root.SetAttribute("stocks",stocks.Text);root.SetAttribute("endZone",endZone.Value.ToString(Inv));root.SetAttribute("offset",offset.Value.ToString(Inv));root.SetAttribute("topExtension2",topExtension.SelectedIndex.ToString(Inv));root.SetAttribute("allowance",allowance.SelectedIndex.ToString(Inv));foreach(var pair in BbsFields())root.SetAttribute(pair.Key,pair.Value.Text);root.SetAttribute("bbsStatus",bbsStatus.SelectedIndex.ToString(Inv));
  foreach(var s in sources){var e=doc.CreateElement("Source");e.SetAttribute("name",s[1]);PowPackedText.Write(e,s[0]);root.AppendChild(e);}
  foreach(DataGridViewRow r in spans.Rows){if(r.IsNewRow)continue;var e=doc.CreateElement("Span");foreach(var c in new[]{"Line","Mark","Ln","Left","Right","Slab","Qty"})e.SetAttribute(c.ToLowerInvariant(),Cell(r,c));e.SetAttribute("include",(!(r.Cells["Include"].Value is bool)||(bool)r.Cells["Include"].Value).ToString());root.AppendChild(e);}
  foreach(var o in overrides){var e=doc.CreateElement("Edit");e.SetAttribute("mark",o.Key);if(o.Value.Length.HasValue)e.SetAttribute("length",o.Value.Length.Value.ToString("R",Inv));if(o.Value.PerLine.HasValue)e.SetAttribute("perLine",o.Value.PerLine.Value.ToString(Inv));if(o.Value.Deleted)e.SetAttribute("deleted","true");root.AppendChild(e);}
  WriteMemberSchedules(root);foreach(var m in memberPieces){var e=doc.CreateElement("MemberBar");e.SetAttribute("group",m.Group);e.SetAttribute("line",m.Line);e.SetAttribute("mark",m.BarMark);e.SetAttribute("location",m.Location);e.SetAttribute("dia",m.Diameter.ToString(Inv));e.SetAttribute("grade",m.Grade.ToString(Inv));e.SetAttribute("perLine",m.PerLine.ToString(Inv));e.SetAttribute("lines",m.Lines.ToString(Inv));e.SetAttribute("length",m.Length.ToString("R",Inv));e.SetAttribute("shape",m.Shape);e.SetAttribute("secB",m.SecB.ToString("R",Inv));e.SetAttribute("secH",m.SecH.ToString("R",Inv));root.AppendChild(e);}
  foreach(var a in added){var e=doc.CreateElement("AddedBar");e.SetAttribute("mark",a.BarMark);e.SetAttribute("line",a.Line);e.SetAttribute("span",a.Span.ToString(Inv));e.SetAttribute("dia",a.Diameter.ToString(Inv));e.SetAttribute("length",a.Length.ToString("R",Inv));e.SetAttribute("perLine",a.PerLine.ToString(Inv));e.SetAttribute("location",a.Location);e.SetAttribute("shape",a.Shape);root.AppendChild(e);}
  return doc.OuterXml;}
 KeyValuePair<string,TextBox>[] BbsFields(){return new[]{new KeyValuePair<string,TextBox>("bbsNo",bbsNo),new KeyValuePair<string,TextBox>("bbsRev",bbsRev),new KeyValuePair<string,TextBox>("preparedBy",preparedBy),new KeyValuePair<string,TextBox>("checkedBy",checkedBy),new KeyValuePair<string,TextBox>("approvedBy",approvedBy)};}
 internal void OpenProjectXml(string xml){var doc=new XmlDocument{XmlResolver=null};using(var reader=XmlReader.Create(new StringReader(xml),new XmlReaderSettings{XmlResolver=null,DtdProcessing=DtdProcessing.Prohibit,MaxCharactersInDocument=0}))doc.Load(reader);var root=doc.DocumentElement;if(root==null||root.Name!="BeamCuttingList"||root.GetAttribute("version")!="1")throw new Exception("This is not a beam cutting list file.");
  var files=root.SelectNodes("Source").Cast<XmlElement>().Select(e=>new[]{PowPackedText.Read(e),e.GetAttribute("name")}).ToList();filling=true;try{spans.Rows.Clear();if(files.Count>0)AddSources(files,true);else{sources.Clear();schedule.Clear();}
   if(config.Items.Contains(root.GetAttribute("config")))config.SelectedItem=root.GetAttribute("config");int f;if(int.TryParse(root.GetAttribute("frame"),out f)&&f>=0&&f<frame.Items.Count)frame.SelectedIndex=f;if(root.HasAttribute("rounding"))rounding.Text=root.GetAttribute("rounding");decimal v;if(decimal.TryParse(root.GetAttribute("cover"),NumberStyles.Float,Inv,out v))cover.Value=Math.Max(cover.Minimum,Math.Min(cover.Maximum,v));if(decimal.TryParse(root.GetAttribute("spacerDia"),NumberStyles.Float,Inv,out v))spacerDia.Value=Math.Max(spacerDia.Minimum,Math.Min(spacerDia.Maximum,v));if(decimal.TryParse(root.GetAttribute("spacerSpacing"),NumberStyles.Float,Inv,out v))spacerSpacing.Value=Math.Max(spacerSpacing.Minimum,Math.Min(spacerSpacing.Maximum,v));if(longest.Items.Contains(root.GetAttribute("longest")))longest.SelectedItem=root.GetAttribute("longest");if(root.HasAttribute("stocks"))stocks.Text=root.GetAttribute("stocks");if(decimal.TryParse(root.GetAttribute("endZone"),NumberStyles.Float,Inv,out v))endZone.Value=Math.Max(endZone.Minimum,Math.Min(endZone.Maximum,v));if(decimal.TryParse(root.GetAttribute("offset"),NumberStyles.Float,Inv,out v))offset.Value=Math.Max(offset.Minimum,Math.Min(offset.Maximum,v));if(int.TryParse(root.GetAttribute("topExtension2"),out f)&&f>=0&&f<topExtension.Items.Count)topExtension.SelectedIndex=f;else if(int.TryParse(root.GetAttribute("topExtension"),out f))topExtension.SelectedIndex=f==0?1:0;/* v1.44 files: 0 = Ln/3, 1 = Ln/4 */
   if(int.TryParse(root.GetAttribute("allowance"),out f)&&f>=0&&f<allowance.Items.Count)allowance.SelectedIndex=f;if(int.TryParse(root.GetAttribute("bbsStatus"),out f)&&f>=0&&f<bbsStatus.Items.Count)bbsStatus.SelectedIndex=f;foreach(var pair in BbsFields())if(root.HasAttribute(pair.Key))pair.Value.Text=root.GetAttribute(pair.Key);
   overrides.Clear();added.Clear();foreach(XmlElement e in root.SelectNodes("Edit")){var o=new CutOverride{Deleted=e.GetAttribute("deleted")=="true"};double dv;int iv;if(double.TryParse(e.GetAttribute("length"),NumberStyles.Float,Inv,out dv))o.Length=dv;if(int.TryParse(e.GetAttribute("perLine"),out iv))o.PerLine=iv;overrides[e.GetAttribute("mark")]=o;}
   ReadMemberSchedules(root);memberPieces.Clear();foreach(XmlElement e in root.SelectNodes("MemberBar")){Func<string,int> ni=k=>{int iv;int.TryParse(e.GetAttribute(k),NumberStyles.Integer,Inv,out iv);return iv;};Func<string,double> nd=k=>{double dv2;double.TryParse(e.GetAttribute(k),NumberStyles.Float,Inv,out dv2);return dv2;};memberPieces.Add(new CutPiece{Group=e.GetAttribute("group"),Line=e.GetAttribute("line"),BarMark=e.GetAttribute("mark"),Location=e.GetAttribute("location"),Diameter=ni("dia"),Grade=ni("grade"),PerLine=ni("perLine"),Lines=ni("lines"),Length=nd("length"),Shape=e.GetAttribute("shape"),SecB=nd("secB"),SecH=nd("secH")});}
   foreach(XmlElement e in root.SelectNodes("AddedBar")){double dv;int sp,dia,pl;double.TryParse(e.GetAttribute("length"),NumberStyles.Float,Inv,out dv);int.TryParse(e.GetAttribute("span"),out sp);int.TryParse(e.GetAttribute("dia"),out dia);int.TryParse(e.GetAttribute("perLine"),out pl);added.Add(new CutPiece{BarMark=e.GetAttribute("mark"),Line=e.GetAttribute("line"),Span=sp,Diameter=dia,Length=dv,PerLine=pl,Location=e.GetAttribute("location"),Shape=e.GetAttribute("shape"),Manual=true});}
   foreach(XmlElement e in root.SelectNodes("Span")){int i=spans.Rows.Add();var r=spans.Rows[i];foreach(var c in new[]{"Line","Ln","Left","Right","Slab","Qty"})r.Cells[c].Value=e.GetAttribute(c.ToLowerInvariant());string m=e.GetAttribute("mark");r.Cells["Mark"].Value=schedule.ContainsKey(m)?m:null;r.Cells["Include"].Value=e.GetAttribute("include")!="False";}}
  finally{filling=false;}Calculate();saved=State();}
 string State(){try{return ProjectXml();}catch(Exception){return "";}}
 bool SaveDialog(){if(schedule.Count==0)throw new Exception("Load a beam schedule first.");using(var d=new SaveFileDialog{Filter="Beam cutting list|*.beam-cutting.xml",FileName="Beam-Cutting-List.beam-cutting.xml"}){if(d.ShowDialog(this)!=DialogResult.OK)return false;string xml=ProjectXml();string temp=d.FileName+"."+Guid.NewGuid().ToString("N")+".tmp";try{File.WriteAllText(temp,xml,new UTF8Encoding(false));File.Copy(temp,d.FileName,true);}finally{if(File.Exists(temp))File.Delete(temp);}saved=xml;status.ForeColor=PowTheme.Teal;status.Text="Saved "+Path.GetFileName(d.FileName)+".";return true;}}
 void Save(){SaveDialog();}
 /* columns, slabs and footings of the open Program of Works (owner, 20 November 2026) */
 void LoadMembers(){var pow=ProgramOfWorksForm.Current;if(pow==null)throw new Exception("Open the Bill of Quantities with its columns, slabs and footings computed, then load them here.");var sources=pow.BbsSources();if(sources.Count==0)throw new Exception("The Bill of Quantities has no computed columns, slabs or footings yet.");var notes=new List<string>();var pieces=MemberBbs.Pieces(sources,notes);memberPieces.Clear();memberPieces.AddRange(pieces);Calculate();
  status.ForeColor=PowTheme.Teal;status.Text="Loaded from the Bill of Quantities: "+string.Join(", ",MemberBbs.Kinds.Select(k=>new{k,n=sources.Count(x=>x.Kind==k)}).Where(x=>x.n>0).Select(x=>x.n+" "+x.k.ToLowerInvariant()+(x.n>1?"s":"")))+" - "+pieces.Count+" bar marks."+(notes.Count>0?" "+string.Join(" ",notes):"");}
 void Open(){using(var d=new OpenFileDialog{Filter="Beam cutting list|*.beam-cutting.xml"})if(d.ShowDialog(this)==DialogResult.OK)OpenProjectXml(File.ReadAllText(d.FileName));}
}
